    "/banking/reconcile": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        /**
         * Mark a single payment as cleared / reconciled
         * @description Sets `cleared_date`, `reference_no`, and `payment_method` on the
         *     matching row in the source payment table
         *     (`customer_receipts`, `vendor_payments`, `write_checks`,
         *     `bank_deposits`, or `fund_transfers`).
         *     Requires `accountant` role or admin.
         */
        put: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody: {
                content: {
                    "application/json": {
                        /**
                         * @description One of `customer_receipt`, `vendor_payment`, `write_check`, `bank_deposit`, `fund_transfer`.
                         * @example customer_receipt
                         */
                        sourceType: string;
                        /**
                         * @description Primary key of the source document.
                         * @example 42
                         */
                        sourceId: number;
                        /**
                         * Format: date
                         * @description The date the transaction cleared the bank. Omit to leave unchanged.
                         */
                        clearedDate?: string;
                        /** @description Bank reference / cheque number. Omit to leave unchanged. */
                        referenceNo?: string;
                        /** @description Payment method ID. Omit to leave unchanged. */
                        paymentMethod?: number;
                    };
                };
            };
            responses: {
                /** @description Row updated successfully */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            /** @description Number of rows updated (1 on success). */
                            updated?: number;
                        };
                    };
                };
                400: components["responses"]["BadRequest"];
                401: components["responses"]["Unauthorized"];
                /** @description Forbidden — accountant role required */
                403: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content?: never;
                };
            };
        };
        post?: never;
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
